\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-pinched-collision-split}
	\lean{MIPStarRE.QPBT.pinched_coarse_sub_fine_eq}
	\leanok
	\uses{def:pasting-tensor-placement}
	Let $G_{g_2}$ be a measurement on the second tensor factor, let $Q_{a_2}$ be
	its coarse-graining along an evaluation map, let $P_{a_1}$ be a measurement,
	and let $\ket{\psi}$ be a state. Then
	\[
		\sum_{a_2} \bra{\psi} Q_{a_2} \ot
				\sum_{a_1} P_{a_1} Q_{a_2} P_{a_1} \ket{\psi}
			- \sum_{g_2} \bra{\psi} G_{g_2} \ot
				\sum_{a_1} P_{a_1} G_{g_2} P_{a_1} \ket{\psi}
			= \sum_{\substack{g_2 \neq g_2' \\ \text{colliding}}} \sum_{a_1}
				\bra{\psi} G_{g_2'} \ot P_{a_1} G_{g_2} P_{a_1} \ket{\psi}\,,
	\]
	where a pair is colliding when the two codewords have the same evaluation.
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-tensor-placement}
	Each coarse effect is the sum of the fine effects over the fiber of the
	evaluation map, and both tensor placement and the quadratic form are
	additive, so the coarse sum is the sum over all pairs of fine codewords with
	equal evaluations. The diagonal pairs reproduce the fine sum and the
	remaining pairs are the colliding ones.
\end{proof}

